<?php
/**  * Verify Shift Migration Status  *  * This script checks if the shift migration has been applied  */  require_once __DIR__ . '/../public/db_connect.php';  header('Content-Type: text/plain');  echo "==============================================\n";
echo "SHIFT MIGRATION VERIFICATION\n";
echo "==============================================\n\n";  try {  // Check if columns exist  $stmt = $pdo->query("SHOW COLUMNS FROM users LIKE 'assigned_shift'");  $assigned_shift_exists = $stmt->rowCount() > 0;  $stmt = $pdo->query("SHOW COLUMNS FROM users LIKE 'shift_start_time'");  $shift_start_exists = $stmt->rowCount() > 0;  $stmt = $pdo->query("SHOW COLUMNS FROM users LIKE 'shift_end_time'");  $shift_end_exists = $stmt->rowCount() > 0;  echo "[Column Checks]\n";  echo "- assigned_shift: " . ($assigned_shift_exists ? " EXISTS" : "MISSING") . "\n";  echo "- shift_start_time: " . ($shift_start_exists ? " EXISTS" : "MISSING") . "\n";  echo "- shift_end_time: " . ($shift_end_exists ? " EXISTS" : "MISSING") . "\n\n";  if ($assigned_shift_exists && $shift_start_exists && $shift_end_exists) {  echo " All shift columns are present!\n\n";  // Check user assignments  echo "[User Shift Assignments]\n";  $stmt = $pdo->query("  SELECT  role,  assigned_shift,  COUNT(*) as count  FROM users  GROUP BY role, assigned_shift  ORDER BY role, assigned_shift  ");  $results = $stmt->fetchAll(PDO::FETCH_ASSOC);  foreach ($results as $row) {  $shift_display = $row['assigned_shift'] ?? 'Not Assigned';  echo "- {$row['role']}: {$shift_display} ({$row['count']} user(s))\n";  }  echo "\n==============================================\n";  echo " MIGRATION IS COMPLETE\n";  echo "==============================================\n\n";  echo "You can now:\n";  echo "1. Go to Admin → User Management\n";  echo "2. Edit staff accounts to assign shifts\n";  echo "3. Set shift times for each staff member\n\n";  } else {  echo "Migration is incomplete. Some columns are missing.\n";  echo "Please run: php database/apply_shift_migration.php\n\n";  }  } catch (PDOException $e) {  echo "\nERROR: " . $e->getMessage() . "\n";
}
?>
